/* Distinct public names under one MAIN comparator, proper independent peers.
 * Named comparators differ only in counters and return exactly the same order. */
#define _GNU_SOURCE
#include <lmdb.h>
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>
#include <errno.h>
static unsigned main_calls,lower_calls,upper_calls;static int errors;
static void need(int b,const char*s){if(!b){fprintf(stderr,"named fold fatal: %s\n",s);exit(2);}}
static void ok(int rc,const char*s){if(rc){fprintf(stderr,"%s: %d %s\n",s,rc,mdb_strerror(rc));exit(2);}}
static int ordinary(const MDB_val*a,const MDB_val*b){size_t n=a->mv_size<b->mv_size?a->mv_size:b->mv_size;int rc=memcmp(a->mv_data,b->mv_data,n);return rc?rc:(a->mv_size>b->mv_size)-(a->mv_size<b->mv_size);}
static int lower_cmp(const MDB_val*a,const MDB_val*b){lower_calls++;return ordinary(a,b);}static int upper_cmp(const MDB_val*a,const MDB_val*b){upper_calls++;return ordinary(a,b);}
static int fold(const MDB_val*a,const MDB_val*b){main_calls++;size_t n=a->mv_size<b->mv_size?a->mv_size:b->mv_size;for(size_t i=0;i<n;i++){unsigned char x=((unsigned char*)a->mv_data)[i],y=((unsigned char*)b->mv_data)[i];if(x>='A'&&x<='Z')x=(unsigned char)(x+'a'-'A');if(y>='A'&&y<='Z')y=(unsigned char)(y+'a'-'A');if(x!=y)return(x>y)-(x<y);}return(a->mv_size>b->mv_size)-(a->mv_size<b->mv_size);}
static MDB_val val(const char*s){return(MDB_val){strlen(s),(void*)s};}
static MDB_env*env(const char*p,unsigned flags){MDB_env*e;ok(mdb_env_create(&e),"create");ok(mdb_env_set_maxdbs(e,12),"maxdbs");ok(mdb_env_set_mapsize(e,16u*1024u*1024u),"mapsize");ok(mdb_env_open(e,p,flags|MDB_NOTLS,0600),"open");return e;}
static MDB_txn*begin(MDB_env*e,unsigned flags){MDB_txn*t;ok(mdb_txn_begin(e,NULL,flags,&t),"begin");return t;}
static void main_fold(MDB_txn*t){MDB_dbi d;ok(mdb_dbi_open(t,NULL,0,&d),"open MAIN before comparator");ok(mdb_set_compare(t,d,fold),"MAIN fold before catalog/data");}
static void expected(int rc,int want,const char*label){printf("%s=%d\n",label,rc);if(rc!=want){fprintf(stderr,"named fold mismatch %s got=%d expected=%d\n",label,rc,want);errors++;}}
static void check_flags(MDB_txn*t,MDB_dbi d,unsigned want,const char*label){unsigned flags=~0u;int rc=mdb_dbi_flags(t,d,&flags);expected(rc,0,label);if(!rc){printf("%s.value=%u\n",label,flags);if(flags!=want){fprintf(stderr,"named fold mismatch %s flags%u expected%u\n",label,flags,want);errors++;}}}
static void get(MDB_txn*t,MDB_dbi d,int want,const char*label){MDB_val k=val("k"),v;int rc=mdb_get(t,d,&k,&v);expected(rc,want,label);if(!rc){need(v.mv_size==1&&*(char*)v.mv_data=='B',"real B bytes");puts("value=B");}}
static void authority(MDB_txn*t,MDB_dbi d,int lower,const char*label){MDB_val a=val("a"),z=val("z");lower_calls=upper_calls=0;int rc=mdb_cmp(t,d,&a,&z);printf("%s.sign=%d lower=%u upper=%u\n",label,(rc>0)-(rc<0),lower_calls,upper_calls);if(!(rc<0&&(lower?lower_calls==1&&upper_calls==0:upper_calls==1&&lower_calls==0))){fprintf(stderr,"named fold mismatch %s comparator authority\n",label);errors++;}}
static void peer(const char*path,int changed){MDB_env*e=env(path,0);MDB_txn*t=begin(e,0);main_fold(t);MDB_dbi old;ok(mdb_dbi_open(t,"x",0,&old),"peer lower open");ok(mdb_drop(t,old,1),"peer closes only own lower alias");/* old never used again. */MDB_dbi upper;ok(mdb_dbi_open(t,"X",MDB_CREATE|(changed?MDB_DUPSORT:0),&upper),"peer upper create");ok(mdb_set_compare(t,upper,upper_cmp),"upper comparator before data");MDB_val k=val("k"),v=val("B");ok(mdb_put(t,upper,&k,&v,0),"upper B put");ok(mdb_txn_commit(t),"peer commit");mdb_env_close(e);}
static void scenario(const char*self,const char*path,int changed){need(!mkdir(path,0700),"fresh scenario");MDB_env*e=env(path,0);MDB_txn*t=begin(e,0);main_fold(t);MDB_dbi lower;ok(mdb_dbi_open(t,"x",MDB_CREATE,&lower),"seed lower");ok(mdb_set_compare(t,lower,lower_cmp),"lower comparator before seed data");MDB_val k=val("k"),v=val("A");ok(mdb_put(t,lower,&k,&v,0),"seed A");ok(mdb_txn_commit(t),"seed commit");MDB_txn*old=begin(e,MDB_RDONLY);MDB_val borrowed;ok(mdb_get(old,lower,&k,&borrowed),"old A borrow");MDB_cursor*c;ok(mdb_cursor_open(old,lower,&c),"old A cursor");ok(mdb_cursor_get(c,&k,&v,MDB_SET),"old A position");fflush(stdout);pid_t p=fork();need(p>=0,"fork peer");if(!p){char mode[8];snprintf(mode,sizeof mode,"%d",changed);execl(self,self,"--peer",path,mode,(char*)NULL);_exit(127);}int status;need(waitpid(p,&status,0)==p&&WIFEXITED(status)&&!WEXITSTATUS(status),"peer completed");t=begin(e,MDB_RDONLY);MDB_dbi l=0,u=0;ok(mdb_dbi_open(t,"x",0,&l),"cached lower open");need(l==lower,"cached lower identity");int ru=mdb_dbi_open(t,"X",0,&u);expected(ru,0,"parent.upper.open");if(!ru)ok(mdb_set_compare(t,u,upper_cmp),"parent upper comparator before data");printf("parent.ids.lower=%u upper=%d distinct=%d\n",l,ru?-1:(int)u,!ru&&l!=u);if(!ru&&l==u){fputs("named fold mismatch parent aliases collapsed\n",stderr);errors++;}check_flags(t,l,0,"parent.lower.flags");get(t,l,changed?MDB_INCOMPATIBLE:0,"parent.lower.get");authority(t,l,1,"parent.lower.cmp");if(!ru){check_flags(t,u,changed?MDB_DUPSORT:0,"parent.upper.flags");get(t,u,0,"parent.upper.get");authority(t,u,0,"parent.upper.cmp");}mdb_txn_abort(t);need(borrowed.mv_size==1&&*(char*)borrowed.mv_data=='A',"old borrowed A survives");ok(mdb_cursor_get(c,&k,&v,MDB_GET_CURRENT),"old cursor remains A");need(v.mv_size==1&&*(char*)v.mv_data=='A',"old cursor A bytes");mdb_cursor_close(c);mdb_txn_abort(old);mdb_env_close(e);
 e=env(path,MDB_RDONLY);t=begin(e,MDB_RDONLY);main_fold(t);l=u=0;int rl=mdb_dbi_open(t,"x",0,&l);expected(rl,0,"fresh.lower.open");if(!rl)ok(mdb_set_compare(t,l,lower_cmp),"fresh lower comparator before data");ru=mdb_dbi_open(t,"X",0,&u);expected(ru,0,"fresh.upper.open");if(!ru)ok(mdb_set_compare(t,u,upper_cmp),"fresh upper comparator before data");printf("fresh.ids.lower=%d upper=%d distinct=%d\n",rl?-1:(int)l,ru?-1:(int)u,!rl&&!ru&&l!=u);if(!rl&&!ru&&l==u){fputs("named fold mismatch fresh aliases collapsed\n",stderr);errors++;}MDB_dbi again=0;if(!rl){ok(mdb_dbi_open(t,"x",0,&again),"repeat lower");need(again==l,"repeat lower identity");check_flags(t,l,changed?MDB_DUPSORT:0,"fresh.lower.flags");get(t,l,0,"fresh.lower.get");authority(t,l,1,"fresh.lower.cmp");}if(!ru){ok(mdb_dbi_open(t,"X",0,&again),"repeat upper");need(again==u,"repeat upper identity");check_flags(t,u,changed?MDB_DUPSORT:0,"fresh.upper.flags");get(t,u,0,"fresh.upper.get");authority(t,u,0,"fresh.upper.cmp");}mdb_txn_abort(t);mdb_env_close(e);}
int main(int argc,char**argv){setvbuf(stdout,NULL,_IONBF,0);Dl_info provider;need(dladdr((void*)mdb_env_open,&provider)&&provider.dli_fname,"provider");fprintf(stderr,"PROVIDER %s\n",provider.dli_fname);if(argc==4&&!strcmp(argv[1],"--peer")){peer(argv[2],atoi(argv[3]));return 0;}if(argc!=2)return 2;need(!mkdir(argv[1],0700),"root directory");for(int changed=0;changed<2;changed++){char path[4096];int n=snprintf(path,sizeof path,"%s/changed%d",argv[1],changed);need(n>0&&(size_t)n<sizeof path,"path");printf("scenario=G14-named-fold-changed%d\n",changed);scenario(argv[0],path,changed);}printf("named-fold-complete errors=%d\n",errors);return errors?1:0;}
